147	  fn fold_module(&mut self, mut node: Module) -> Module {
148	    // Pre-pass to find all macro imports.
149	    node.body.retain(|item| {
150	      if let ModuleItem::ModuleDecl(decl) = &item {
151	        if let ModuleDecl::Import(import) = &decl {
152	          if matches!(&import.with, Some(with) if is_macro(with)) {
153	            self.add_macro(import);
154	            return false;
155	          }
156	        }
157	      }
158	
159	      true
160	    });
161	
162	    // Only process the rest of the AST if we found any macro imports.
163	    if !self.macros.is_empty() {
164	      node = node.fold_children_with(self);
165	    }
166	
167	    node
168	  }
