37	  pub fn transform_async(opts: JsObject, env: Env) -> napi::Result<JsObject> {
38	    let call_macro_tsfn = if opts.has_named_property("callMacro")? {
39	      let func = opts.get_named_property::<JsUnknown>("callMacro")?;
40	      if let Ok(func) = func.try_into() {
41	        Some(env.create_threadsafe_function(
42	          &func,
43	          0,
44	          |ctx: ThreadSafeCallContext<CallMacroMessage>| {
45	            let src = ctx.env.create_string(&ctx.value.src)?.into_unknown();
46	            let export = ctx.env.create_string(&ctx.value.export)?.into_unknown();
47	            let args = js_value_to_napi(JsValue::Array(ctx.value.args), ctx.env)?;
48	            let loc = ctx.env.to_js_value(&ctx.value.loc)?.into_unknown();
49	            Ok(vec![src, export, args, loc])
